const resposta = $('Obter token').first().json ?? {};
const status = Number(resposta.statusCode ?? 0);
const motivo = String(resposta.body?.errors?.motivo ?? '');
const PEDE_REAUTORIZACAO = new Set(['reauth_pending', 'sem_token', 'conexao_revogada']);

let falha;
if (status === 409 && PEDE_REAUTORIZACAO.has(motivo)) {
  falha = { causa: 'reauth_pending', detalhe: `cofre de tokens: ${motivo}; reautorize a conexão` };
} else if (status === 429) {
  falha = { causa: 'limite_de_uso', detalhe: 'cofre de tokens: pedidos de token demais para esta execução', pausa: 'limite_temporario', minutos: 5 };
} else if (status === 0 || status >= 500) {
  falha = { causa: 'api_recusou', detalhe: `cofre de tokens indisponível (HTTP ${status || 'sem resposta'})` };
} else {
  falha = { causa: 'falha_coletor', detalhe: `cofre de tokens recusou o pedido (HTTP ${status}${motivo ? `, ${motivo}` : ''})` };
}

return [{ json: { linhas: [], volumetria: { linhas: 0, bytes: 0, requests: 0, duracaoMs: 0 }, falhas: [falha], avisos: [], requests: 0 } }];

const { fonte, janela, modo } = $json;
const VERSAO_DA_API_META = 'v27.0';
const pageId = String(fonte?.externalId ?? '');
const DIAS_DE_LEADS = 30;
const diaDeHoje = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const inicioPadrao = Date.parse(`${diaDeHoje}T00:00:00-03:00`) - DIAS_DE_LEADS * 86400000;
const inicioDaJanela = modo === 'incremental' && typeof janela?.start === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(janela.start) ? Date.parse(`${janela.start}T00:00:00-03:00`) : inicioPadrao;
const leadsDesde = Math.floor(inicioDaJanela / 1000) - 1;
return [{ json: { inicio: Date.now(), versaoApi: VERSAO_DA_API_META, pageId, pageIdValido: /^\d{5,25}$/.test(pageId), leadsDesde } }];

const contexto = $('Montar requisição').first().json;
const respostaDoToken = $('Token da Página').first().json ?? {};
const tokenDaPagina = typeof respostaDoToken.body?.access_token === 'string' ? respostaDoToken.body.access_token : '';
const comResposta = (json) => json && (json.statusCode !== undefined || json.error);
function paginasDeFormularios() {
  try {
    return $('Listar formulários').all().map((item) => item.json).filter(comResposta);
  } catch {
    return [];
  }
}
const paginas = tokenDaPagina ? paginasDeFormularios() : [];
const paginasDeLeads = tokenDaPagina ? $input.all().map((item) => item.json).filter(comResposta) : [];
const requests = 1 + paginas.length + paginasDeLeads.length;
const bytes = [...paginas, ...paginasDeLeads].reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);
const SEM_ANUNCIO = 'sem_anuncio';
const SEM_CAMPANHA = 'sem_campanha';
const FUSO = 'America/Sao_Paulo';
const ROTULO_MAXIMO = 200;

const PAUSA_DO_USO_META = 75;
const CODIGOS_DE_LIMITE_META = [4, 17, 32, 341, 613];
function limiteDaMeta(statusCode, erro) {
  const codigo = Number(erro?.code);
  return statusCode === 429 || CODIGOS_DE_LIMITE_META.includes(codigo) || (codigo >= 80000 && codigo <= 80014)
    || /request limit reached|too many calls|rate limit/i.test(String(erro?.message ?? ''));
}
function lerJson(valor) {
  if (valor && typeof valor === 'object') return valor;
  try {
    return typeof valor === 'string' ? JSON.parse(valor) : null;
  } catch {
    return null;
  }
}
function cabecalho(resposta, nome) {
  const cabecalhos = resposta?.headers ?? {};
  return cabecalhos[nome] ?? cabecalhos[nome.toLowerCase()] ?? null;
}
function usoDaMeta(respostas) {
  let percentual = null;
  let minutosParaRecuperar = 0;
  for (const resposta of respostas) {
    const throttle = lerJson(cabecalho(resposta, 'x-fb-ads-insights-throttle'));
    const negocio = lerJson(cabecalho(resposta, 'x-business-use-case-usage'));
    const aplicativo = lerJson(cabecalho(resposta, 'x-app-usage'));
    const entradas = negocio ? Object.values(negocio).flat() : [];
    const valores = [
      throttle?.acc_id_util_pct, throttle?.app_id_util_pct,
      aplicativo?.call_count, aplicativo?.total_cputime, aplicativo?.total_time,
      ...entradas.flatMap((entrada) => [entrada?.call_count, entrada?.total_cputime, entrada?.total_time]),
    ].map(Number).filter(Number.isFinite);
    if (valores.length > 0) percentual = Math.max(percentual ?? 0, ...valores);
    for (const entrada of entradas) {
      const minutos = Number(entrada?.estimated_time_to_regain_access);
      if (Number.isFinite(minutos)) minutosParaRecuperar = Math.max(minutosParaRecuperar, minutos);
    }
  }
  return { percentual, minutosParaRecuperar };
}
function avisosDaMeta(respostas, versaoApi) {
  const avisos = [];
  const servidas = new Set(respostas.map((resposta) => cabecalho(resposta, 'facebook-api-version')).filter(Boolean).map(String));
  for (const servida of servidas) {
    if (servida !== versaoApi) avisos.push({ tipo: 'versao_da_api', detalhe: `pedida ${versaoApi}, servida ${servida}` });
  }
  const alerta = respostas.map((resposta) => cabecalho(resposta, 'x-ad-api-version-warning')).find(Boolean);
  if (alerta) avisos.push({ tipo: 'versao_da_api', detalhe: String(alerta).slice(0, 500) });
  const niveis = new Set(respostas.flatMap((resposta) => {
    const negocio = lerJson(cabecalho(resposta, 'x-business-use-case-usage'));
    return negocio ? Object.values(negocio).flat().map((entrada) => entrada?.ads_api_access_tier).filter(Boolean) : [];
  }));
  if (niveis.has('development_access')) avisos.push({ tipo: 'nivel_de_acesso', detalhe: 'app Meta em development_access: limites de uso baixos; o Standard Access exige App Review (verificação de empresa)' });
  const uso = usoDaMeta(respostas);
  if (uso.percentual !== null && uso.percentual > PAUSA_DO_USO_META) {
    avisos.push({ tipo: 'uso_de_cota', detalhe: `uso da Meta em ${uso.percentual}%${uso.minutosParaRecuperar ? `, recupera em ${uso.minutosParaRecuperar} min` : ''}` });
  }
  return avisos;
}

const avisos = avisosDaMeta([respostaDoToken, ...paginas, ...paginasDeLeads], contexto.versaoApi);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      avisos,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

function semToken(texto) {
  let limpo = String(texto ?? '');
  if (tokenDaPagina) limpo = limpo.split(tokenDaPagina).join('[removido]');
  return limpo.replace(/access_token=[^&\s"']+/g, 'access_token=[removido]').slice(0, 500);
}

function falhaDe(resposta) {
  if (resposta.error) return { causa: 'api_recusou', detalhe: semToken(`falha de rede: ${resposta.error?.message ?? resposta.error}`) };
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = resposta.body?.error;
  const detalhe = semToken(erro?.message || `HTTP ${resposta.statusCode}`);
  if (limiteDaMeta(resposta.statusCode, erro)) return { causa: 'limite_de_uso', detalhe };
  const semAcesso = resposta.statusCode === 401 || resposta.statusCode === 403 || [190, 10, 200].includes(erro?.code);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

if (!contexto.pageIdValido) return devolver([], [{ causa: 'api_recusou', detalhe: 'id da Página inválido' }]);

const falhaDoToken = falhaDe(respostaDoToken);
if (falhaDoToken) return devolver([], [falhaDoToken]);
if (!tokenDaPagina) {
  return devolver([], [{
    causa: 'reauth_pending',
    detalhe: 'A Meta não entregou o token da Página: quem autorizou precisa da tarefa ADVERTISE, MANAGE ou MANAGE_LEADS nela.',
  }]);
}

const recusada = paginas.map(falhaDe).find(Boolean);
if (recusada) return devolver([], [recusada]);

const texto = (valor) => {
  if (typeof valor !== 'string') return null;
  const limpo = valor.trim();
  return limpo ? limpo.slice(0, ROTULO_MAXIMO) : null;
};
const contagem = (valor) => {
  const numero = typeof valor === 'string' && valor.trim() !== '' ? Number(valor) : valor;
  return typeof numero === 'number' && Number.isFinite(numero) && numero >= 0 ? Math.trunc(numero) : null;
};

const identificadorDeFacebook = (valor) => (typeof valor === 'string' && /^\d{5,25}$/.test(valor) ? valor : null);
const enumeracao = (valor) => (typeof valor === 'string' && /^[A-Z_]{1,40}$/.test(valor) ? valor : null);
const idioma = (valor) => (typeof valor === 'string' && /^[A-Za-z]{2,3}(_[A-Za-z0-9]{2,4})?$/.test(valor) ? valor : null);
const dimensoes = [];
const respostaDaPagina = respostaDoToken.body ?? {};
dimensoes.push({ _tabela: 'dim_pagina', nome: texto(respostaDaPagina.name), categoria: texto(respostaDaPagina.category) });

const porId = new Map();
for (const pagina of paginas) {
  const formularios = Array.isArray(pagina.body?.data) ? pagina.body.data : [];
  for (const formulario of formularios) {
    const formId = typeof formulario?.id === 'string' && /^\d{5,25}$/.test(formulario.id) ? formulario.id : null;
    if (!formId) continue;
    const perguntas = Array.isArray(formulario.questions) ? formulario.questions : [];
    const tipos = [...new Set(perguntas.map((pergunta) => enumeracao(pergunta?.type)).filter(Boolean))].sort();
    dimensoes.push({
      _tabela: 'dim_formulario',
      formId,
      nome: texto(formulario.name),
      status: enumeracao(formulario.status),
      idioma: idioma(formulario.locale),
      perguntasTotal: perguntas.length,
      tiposDePergunta: tipos.join(','),
    });
    porId.set(formId, {
      formId,
      nome: texto(formulario.name),
      status: typeof formulario.status === 'string' && /^[A-Z_]{1,40}$/.test(formulario.status) ? formulario.status : null,
      leadsTotal: contagem(formulario.leads_count),
      leadsExpirados: contagem(formulario.expired_leads_count),
      criadoEm: typeof formulario.created_time === 'string' && formulario.created_time ? formulario.created_time : null,
    });
  }
}

const formatoDoDia = new Intl.DateTimeFormat('en-CA', { timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit' });
const instanteDoLead = (valor) => {
  if (typeof valor !== 'string' || !valor) return null;
  const data = new Date(valor.replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return Number.isNaN(data.getTime()) ? null : data;
};

const falhasDeLeads = paginasDeLeads.map(falhaDe).filter(Boolean);
const leadsPorDia = new Map();
const ultimaPaginaPorFormulario = new Map();
for (const pagina of paginasDeLeads) {
  const leadsDaPagina = Array.isArray(pagina.body?.data) ? pagina.body.data : [];
  const formularioDaPagina = identificadorDeFacebook(leadsDaPagina[0]?.form_id);
  if (formularioDaPagina) ultimaPaginaPorFormulario.set(formularioDaPagina, pagina);
  for (const lead of leadsDaPagina) {
    const formId = identificadorDeFacebook(lead?.form_id);
    const instante = instanteDoLead(lead?.created_time);
    if (!formId || !instante) continue;
    const dataDia = formatoDoDia.format(instante);
    const anuncioId = identificadorDeFacebook(lead.ad_id) ?? SEM_ANUNCIO;
    const campanhaId = identificadorDeFacebook(lead.campaign_id) ?? SEM_CAMPANHA;
    const chave = [formId, dataDia, anuncioId, campanhaId].join('|');
    const anterior = leadsPorDia.get(chave);
    leadsPorDia.set(chave, { _tabela: 'leads_diarios', formId, dataDia, anuncioId, campanhaId, leads: (anterior?.leads ?? 0) + 1 });
  }
}

const linhas = [...porId.values()];
if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);

const truncados = [...ultimaPaginaPorFormulario.entries()].filter(([, pagina]) => Boolean(pagina.body?.paging?.next)).map(([formId]) => formId);
const diasParciais = new Set();
for (const formId of truncados) {
  const dias = [...leadsPorDia.values()].filter((linha) => linha.formId === formId).map((linha) => linha.dataDia).sort();
  if (dias.length > 0) diasParciais.add(`${formId}|${dias[0]}`);
}
const leadsCompletos = falhasDeLeads.length > 0
  ? []
  : [...leadsPorDia.values()].filter((linha) => !diasParciais.has(`${linha.formId}|${linha.dataDia}`));

const todas = [...linhas, ...dimensoes, ...leadsCompletos];
const limiteNosLeads = falhasDeLeads.find((falha) => falha.causa === 'limite_de_uso');
if (limiteNosLeads) return devolver([...linhas, ...dimensoes], [{ causa: 'limite_de_uso', detalhe: semToken(`leads: ${limiteNosLeads.detalhe}`) }]);
const motivos = falhasDeLeads.map((falha) => `leads: ${falha.detalhe}`);
if (truncados.length > 0) motivos.push(`leads acima do teto de paginação (dia mais antigo descartado): ${truncados.join(',')}`);
if (motivos.length > 0) return devolver(todas, [{ causa: 'coleta_incompleta', detalhe: semToken(motivos.join('; ')) }]);
return devolver(todas, []);

const paginas = $input.all().map((item) => item.json);
const ids = [];
for (const pagina of paginas) {
  const formularios = pagina.statusCode >= 200 && pagina.statusCode < 300 && Array.isArray(pagina.body?.data) ? pagina.body.data : [];
  for (const formulario of formularios) {
    if (typeof formulario?.id === 'string' && /^\d{5,25}$/.test(formulario.id) && !ids.includes(formulario.id)) ids.push(formulario.id);
  }
}
if (ids.length === 0) return [{ json: { temFormulario: false } }];
return ids.map((formId) => ({ json: { temFormulario: true, formId } }));
